package com.tradingassistant.monitoring.domain;

import java.time.Instant;
import java.util.Map;
import java.util.Objects;

/** A persisted alert generated by the monitoring engine. */
public record MonitoringAlert(
        String tradeId,
        Instant timestamp,
        MonitoringAlertType type,
        String message,
        Map<String, String> diagnostics) {

    public MonitoringAlert {
        if (tradeId == null || tradeId.isBlank()) {
            throw new IllegalArgumentException("tradeId must not be blank");
        }
        tradeId = tradeId.trim();
        timestamp = Objects.requireNonNull(timestamp, "timestamp must not be null");
        type = Objects.requireNonNull(type, "type must not be null");
        if (message == null || message.isBlank()) {
            throw new IllegalArgumentException("message must not be blank");
        }
        message = message.trim();
        diagnostics = diagnostics == null ? Map.of() : Map.copyOf(diagnostics);
    }
}